1	import { NextRequest, NextResponse } from "next/server";
2	import { siteHostAllowed } from "@/app/api/site/[slug]/site-host";
3	
4	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
5	
6	// The hostname the admin panel answers on, e.g. "ops-7f3k2q.kodely.me".
7	// When set, /admin is reachable ONLY there and 404s on every other host.
8	// When unset (local dev), /admin behaves as it always did.
9	//
10	// This is obscurity, not authorization. Subdomains are not secret: every TLS
11	// certificate is published to public Certificate Transparency logs, so anyone
12	// can search crt.sh for kodely.me and enumerate this name minutes after the
13	// cert is issued. It raises the cost of drive-by scanning and nothing more.
14	// The real gate is the role check in app/admin/layout.tsx and app/admin/page.tsx,
15	// which stays regardless — Next's own proxy docs are explicit that a proxy must
16	// not be the sole authorization boundary, since Server Functions and route
17	// handlers can bypass matcher coverage.
18	const ADMIN_HOST = process.env.KODELY_ADMIN_HOST?.trim().toLowerCase();
19	
20	// Rewritten to when /admin is requested off the admin host. No route exists
21	// here, so Next renders its ordinary not-found page with a 404 — byte-for-byte
22	// what a genuinely nonexistent path returns. A hand-written 404 body would be
23	// distinguishable from a real miss and would advertise that something is here.
24	const NOWHERE = "/_kodely_nonexistent";
25	
26	// A request to <slug>.kodely.site is rewritten to the internal site-serving
27	// API. Everything on the apex app domain (kodely.me / staging.kodely.me)
28	// passes through untouched.
29	export function proxy(req: NextRequest) {
30	  const host = req.headers.get("host") ?? "";
31	  const bareHost = host.split(":")[0].toLowerCase();
32	  const { pathname } = req.nextUrl;
33	
34	  if (bareHost.endsWith(`.${SITES_BASE}`)) {
35	    const slug = bareHost.slice(0, -(SITES_BASE.length + 1));
36	    if (slug && slug !== "www") {
37	      const url = req.nextUrl.clone();
38	      url.pathname = `/api/site/${slug}${pathname === "/" ? "" : pathname}`;
39	      return NextResponse.rewrite(url);
40	    }
41	  }
42	
43	  // The rewrite above is internal — Next does not re-enter this function for it
44	  // — so anything still carrying /api/site/… here asked for that path from the
45	  // outside. On the sites domain and on staging that is legitimate; on the app's
46	  // own domain it means someone is trying to serve a customer's HTML as
47	  // first-party content on kodely.me. Same NOWHERE rewrite as /admin: an
48	  // ordinary Next 404, indistinguishable from a path that never existed, and it
49	  // costs no database round trip. The route handler repeats the check itself.
50	  if (pathname.startsWith("/api/site/")) {
51	    const slug = pathname.split("/")[3] ?? "";
52	    if (!siteHostAllowed(host, slug)) {
53	      const url = req.nextUrl.clone();
54	      url.pathname = NOWHERE;
55	      return NextResponse.rewrite(url);
56	    }
57	  }
58	
59	  if (ADMIN_HOST) {
60	    const onAdminHost = bareHost === ADMIN_HOST;
61	
62	    if (pathname === "/admin" || pathname.startsWith("/admin/")) {
63	      if (!onAdminHost) {
64	        const url = req.nextUrl.clone();
65	        url.pathname = NOWHERE;
66	        return NextResponse.rewrite(url);
67	      }
68	    } else if (onAdminHost && pathname === "/") {
69	      // Landing on the admin host goes straight to the panel rather than the
70	      // marketing site. Everything else on this host still resolves normally —
71	      // /login and /api/auth/* have to work here, because the session cookie
72	      // sets no `domain` and is therefore host-only: a session created on
73	      // kodely.me is never sent to this host. Signing in happens here or the
74	      // panel is unreachable.
75	      const url = req.nextUrl.clone();
76	      url.pathname = "/admin";
77	      return NextResponse.rewrite(url);
78	    }
79	  }
80	
81	  return NextResponse.next();
82	}
83	
84	export const config = {
85	  matcher: ["/((?!_next/static|_next/image|favicon.ico).*)"],
86	};
