74	/** Master off switch. Set KODELY_NOTIFY_DISABLED=1 to stop all sending. */
75	function disabled(): boolean {
76	  return process.env.KODELY_NOTIFY_DISABLED === "1";
77	}
78	
79	/** Compose and log, never hand anything to SMTP. */
80	function dryRun(): boolean {
81	  return process.env.KODELY_NOTIFY_DRY_RUN === "1";
