99	// ── Duplicate suppression, process-local ──────────────────────────────────
100	//
101	// This is the SECOND line of defence only. The real idempotency lives in
102	// lib/notifications/scan.ts, which derives each notification from a state
103	// transition that can only fall inside one cron slot. This map exists to make
104	// a retried or overlapping cron run (or a double-wired inline hook) a no-op
105	// within one process lifetime. It resets on deploy — same trade-off, and the
106	// same honest limitation, as the throttle in app/api/contact/route.ts.
107	
108	const RECENT_TTL_MS = 6 * 60 * 60 * 1000;
109	const RECENT_MAX = 20_000;
110	
111	const globalForNotify = globalThis as unknown as { kodelyNotifySent?: Map<string, number> };
112	const recent: Map<string, number> = (globalForNotify.kodelyNotifySent ??= new Map());
113	
114	/**
115	 * True the first time a given (kind, dedupeKey) is seen, false afterwards.
116	 * The key must identify the *occurrence*, not the person: a ledger row id, a
117	 * build id, a project id — never just a userId for anything repeatable.
118	 */
119	function claim(kind: EmailKind, dedupeKey: string): boolean {
120	  const now = Date.now();
121	  if (recent.size > RECENT_MAX) {
122	    for (const [k, t] of recent) if (now - t > RECENT_TTL_MS) recent.delete(k);
123	    if (recent.size > RECENT_MAX) recent.clear();
124	  }
125	  const key = `${kind}:${dedupeKey}`;
126	  const seen = recent.get(key);
127	  if (seen !== undefined && now - seen < RECENT_TTL_MS) return false;
128	  recent.set(key, now);
129	  return true;
130	}
131	
132	/** Undo a claim when the send didn't actually happen, so a retry can try again. */
133	function release(kind: EmailKind, dedupeKey: string): void {
134	  recent.delete(`${kind}:${dedupeKey}`);
135	}
