137	// ── Delivery ──────────────────────────────────────────────────────────────
138	
139	export type SendResult = {
140	  sent: boolean;
141	  kind: EmailKind;
142	  /** Machine-readable outcome: "sent", "not_configured", "duplicate", ... */
143	  reason: string;
144	};
145	
146	async function deliver(to: string, email: Email): Promise<void> {
147	  if (dryRun()) {
148	    console.log(`[notifications] DRY RUN — would send "${email.subject}" to ${to}`);
149	    return;
150	  }
151	  await transport().sendMail({
152	    from: FROM,
153	    // The bare address, never `Name <addr>`: a display name is user-supplied
154	    // and a CR/LF in it would be header injection (see headerSafe in
155	    // lib/mail.ts). Nothing user-controlled reaches a header from here.
156	    to,
157	    subject: email.subject,
158	    text: email.text,
159	    html: email.html,
160	  });
161	}
