163	/**
164	 * Shared shell for every notification: guards, recipient resolution, dedupe,
165	 * delivery, and the promise that nothing throws.
166	 *
167	 * `build` returns null to abstain — used by every caller to re-check its own
168	 * precondition against the database immediately before sending, so a stale
169	 * scan result can never turn into a wrong email.
170	 */
171	async function send(
172	  kind: EmailKind,
173	  dedupeKey: string,
174	  build: () => Promise<{ to: string; email: Email } | null>,
175	): Promise<SendResult> {
176	  const done = (sent: boolean, reason: string): SendResult => ({ sent, kind, reason });
177	
178	  try {
179	    if (disabled()) return done(false, "disabled");
180	    if (!isMailConfigured() && !dryRun()) return done(false, "not_configured");
181	    if (!claim(kind, dedupeKey)) return done(false, "duplicate");
182	
183	    let target: { to: string; email: Email } | null = null;
184	    try {
185	      target = await build();
186	    } catch (err) {
187	      release(kind, dedupeKey);
188	      console.error(`[notifications] ${kind} lookup failed for ${dedupeKey}:`, err);
189	      return done(false, "lookup_failed");
190	    }
191	
192	    if (!target) {
193	      // Precondition no longer holds — a real "don't send", so keep the claim.
194	      return done(false, "precondition_failed");
195	    }
196	
197	    const allowed = allowlist();
198	    if (allowed && !allowed.has(target.to.toLowerCase())) {
199	      return done(false, "not_allowlisted");
200	    }
201	
202	    try {
203	      await deliver(target.to, target.email);
204	    } catch (err) {
205	      release(kind, dedupeKey);
206	      // Never log the message body or the recipient's other account state.
207	      console.error(`[notifications] ${kind} delivery failed:`, err);
208	      return done(false, "delivery_failed");
209	    }
210	
211	    return done(true, dryRun() ? "dry_run" : "sent");
212	  } catch (err) {
213	    // Belt and braces: this function is called from fire-and-forget paths and
214	    // must not be able to reject.
215	    console.error(`[notifications] ${kind} failed unexpectedly:`, err);
216	    return done(false, "error");
217	  }
218	}
