365	// wire with the cron still running — the same claim key is used on both paths
366	// within a process, and the cron's own scan only looks at closed slots.
367	
368	function fireAndForget(work: Promise<SendResult>): void {
369	  void work.catch((err) => console.error("[notifications] unreachable:", err));
370	}
