4	// Transactional email bodies for Kodely.
5	//
6	// Rules this file exists to enforce:
7	//
8	// 1. PLAIN TEXT IS THE REAL EMAIL. Every message is composed as a list of
9	//    blocks and rendered to text first; the HTML alternative is generated from
10	//    the SAME blocks, so the two can never drift apart or say different things.
11	// 2. NO REMOTE ANYTHING. No images, no tracking pixel, no web fonts, no
12	//    external CSS. Every style is inlined, and the mail makes zero network
13	//    requests when opened — so opening it tells us nothing and leaks nothing.
14	// 3. NOTHING SENSITIVE IN THE BODY. No credentials, tokens, session ids,
15	//    prompt text, generated file contents, or build error strings. Build
16	//    errors in particular can quote the user's own source; they belong in the
17	//    app, behind auth, not in an inbox that may be shared or forwarded.
18	// 4. GENUINELY TRANSACTIONAL. Every one of these is triggered by the sender's
19	//    own account state (their signup, their balance, their build, their
20	//    publish). There is no consent record and no unsubscribe mechanism in this
21	//    product, so nothing here may be promotional or re-engagement-shaped.
22	
23	export type EmailKind = "welcome" | "low_credits" | "build_failed" | "site_published";
24	
25	export type Email = { subject: string; text: string; html: string };
26	
27	export function appUrl(): string {
28	  // Same variable and default as app/api/billing/checkout/route.ts.
29	  return (process.env.APP_URL ?? "https://kodely.me").replace(/\/+$/, "");
30	}
31	
32	// ── Block rendering ───────────────────────────────────────────────────────
33	
34	type Block =
35	  | { kind: "p"; text: string }
36	  | { kind: "ul"; items: string[] }
37	  | { kind: "cta"; label: string; href: string }
38	  | { kind: "link"; label: string; href: string }
39	  | { kind: "note"; text: string };
40	
41	const p = (text: string): Block => ({ kind: "p", text });
42	const ul = (items: string[]): Block => ({ kind: "ul", items });
43	const cta = (label: string, href: string): Block => ({ kind: "cta", label, href });
44	const link = (label: string, href: string): Block => ({ kind: "link", label, href });
45	const note = (text: string): Block => ({ kind: "note", text });
46	
47	function escapeHtml(value: string): string {
48	  return value
49	    .replace(/&/g, "&amp;")
50	    .replace(/</g, "&lt;")
51	    .replace(/>/g, "&gt;")
52	    .replace(/"/g, "&quot;")
53	    .replace(/'/g, "&#39;");
54	}
55	
56	/**
57	 * Blocks only ever carry plain text, and every value is escaped on the way
58	 * into the HTML, so a project name of `<script>` is inert — user-supplied
59	 * strings reach these templates (project names) and must never become markup.
60	 */
61	function safeText(value: string, max = 200): string {
62	  return value.replace(/[\u0000-\u001F\u007F]+/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
63	}
64	
65	/** Only ever used on URLs we build ourselves; a bad one is dropped, not sent. */
66	function safeUrl(value: string): string {
67	  return /^https?:\/\/[^\s"'<>]+$/.test(value) ? value : appUrl();
68	}
69	
70	function wrap(text: string, width = 72): string {
71	  const out: string[] = [];
