import { redirect } from "next/navigation";
import Link from "next/link";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import SubmissionList, { type SubmissionRow } from "./SubmissionList";

export const dynamic = "force-dynamic";

/** Newest page of submissions. Enough for every real inbox; see the note below. */
const PAGE_SIZE = 200;

/**
 * Everything a published site's forms have collected.
 *
 * The values here are UNTRUSTED PUBLIC INPUT — anyone who can load the site can
 * put anything in them. They are rendered as React children and never as HTML:
 * there is no dangerouslySetInnerHTML anywhere on this page or in
 * SubmissionList, so a submission containing markup is displayed as the text it
 * is. That is the whole defence and it must stay that way.
 */
export default async function SubmissionsPage({ params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");
  const { id } = await params;

  const project = await db.project.findFirst({
    where: { id, userId: user.id },
    select: { id: true, name: true, slug: true, publishedAt: true },
  });
  if (!project) redirect("/dashboard");

  const [rows, total, unread] = await Promise.all([
    db.formSubmission.findMany({
      where: { projectId: project.id },
      orderBy: { createdAt: "desc" },
      take: PAGE_SIZE,
      select: {
        id: true,
        formName: true,
        fields: true,
        createdAt: true,
        readAt: true,
        spam: true,
      },
    }),
    db.formSubmission.count({ where: { projectId: project.id } }),
    db.formSubmission.count({ where: { projectId: project.id, readAt: null, spam: false } }),
  ]);

  // `fields` is Json, so its runtime shape is whatever was written — normalise
  // to string pairs HERE rather than trusting the column, and cap what is
  // handed to the client. The write path already caps this; a second cap on
  // read costs nothing and means an old or hand-edited row cannot blow up the
  // page.
  const submissions: SubmissionRow[] = rows.map((r) => {
    const raw = r.fields;
    const pairs: [string, string][] =
      raw !== null && typeof raw === "object" && !Array.isArray(raw)
        ? Object.entries(raw)
            .slice(0, 24)
            .map(([k, v]) => [String(k).slice(0, 64), v === null ? "" : String(v).slice(0, 5000)])
        : [];
    return {
      id: r.id,
      formName: r.formName,
      fields: pairs,
      createdAt: r.createdAt.toISOString(),
      read: r.readAt !== null,
      spam: r.spam,
    };
  });

  return (
    <div className="mx-auto max-w-3xl px-6 py-10">
      <div className="mb-8">
        <Link
          href={`/projects/${project.id}`}
          className="text-sm text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
        >
          ← {project.name}
        </Link>
        <h1 className="mt-2 text-xl font-semibold tracking-tight">Form submissions</h1>
        <p className="mt-1 text-sm text-black/60 dark:text-white/60">
          {total === 0
            ? "Nothing yet."
            : `${total} total${unread > 0 ? ` · ${unread} unread` : ""}${
                total > PAGE_SIZE ? ` · showing the latest ${PAGE_SIZE}` : ""
              }`}
        </p>
      </div>

      {!project.publishedAt && (
        <p className="mb-6 rounded-xl border border-black/10 p-4 text-sm text-black/60 dark:border-white/10 dark:text-white/60">
          This site isn&apos;t published, so its forms can&apos;t receive anything. Submissions are
          only accepted for a live site.
        </p>
      )}

      {total === 0 ? (
        <div className="rounded-xl border border-dashed border-black/15 p-10 text-center text-sm text-black/60 dark:border-white/15 dark:text-white/60">
          When someone fills in a form on your site, it lands here — and we email you.
        </div>
      ) : (
        <SubmissionList projectId={project.id} initial={submissions} />
      )}
    </div>
  );
}

"use client";

import { useState } from "react";

export type SubmissionRow = {
  id: string;
  formName: string;
  /** Ordered key/value pairs, already normalised and capped on the server. */
  fields: [string, string][];
  createdAt: string;
  read: boolean;
  spam: boolean;
};

/**
 * Every value below came from a stranger on the public internet.
 *
 * It is rendered as a React child — `{value}` — and nowhere in this file is
 * there a dangerouslySetInnerHTML, an href built from a field, or a value
 * passed to anything that would parse it. React escapes text children, so a
 * submission of `<img onerror=…>` shows up as those characters. Do not
 * "improve" this by auto-linking addresses or URLs without escaping first.
 */
function Field({ name, value }: { name: string; value: string }) {
  return (
    <div className="grid grid-cols-[minmax(0,7rem)_1fr] gap-3 py-1">
      <div className="truncate text-xs text-black/50 dark:text-white/50" title={name}>
        {name}
      </div>
      <div className="whitespace-pre-wrap break-words text-sm">{value}</div>
    </div>
  );
}

function when(iso: string): string {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleString();
}

export default function SubmissionList({
  projectId,
  initial,
}: {
  projectId: string;
  initial: SubmissionRow[];
}) {
  const [rows, setRows] = useState(initial);
  const [showSpam, setShowSpam] = useState(false);
  const [busy, setBusy] = useState(false);

  const visible = rows.filter((r) => r.spam === showSpam);
  const spamCount = rows.filter((r) => r.spam).length;
  const unread = rows.filter((r) => !r.read && !r.spam).length;

  async function patch(body: { ids?: string[]; read?: boolean; spam?: boolean }) {
    setBusy(true);
    try {
      const res = await fetch(`/api/forms/${projectId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      if (!res.ok) return;
      // Mirror the change locally rather than refetching: the server is the
      // authority, but nothing here depends on a value it computed.
      setRows((current) =>
        current.map((r) => {
          if (body.ids && !body.ids.includes(r.id)) return r;
          return {
            ...r,
            ...(body.read !== undefined ? { read: body.read } : {}),
            ...(body.spam !== undefined ? { spam: body.spam } : {}),
          };
        }),
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <div>
      <div className="mb-4 flex items-center gap-4 text-sm">
        <button
          onClick={() => setShowSpam(false)}
          className={
            showSpam
              ? "text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
              : "font-medium"
          }
        >
          Inbox
        </button>
        <button
          onClick={() => setShowSpam(true)}
          className={
            showSpam
              ? "font-medium"
              : "text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
          }
        >
          Filtered{spamCount > 0 ? ` (${spamCount})` : ""}
        </button>
        <div className="grow" />
        {!showSpam && unread > 0 && (
          <button
            disabled={busy}
            onClick={() => patch({ read: true })}
            className="text-black/60 hover:text-black disabled:opacity-50 dark:text-white/60 dark:hover:text-white"
          >
            Mark all read
          </button>
        )}
      </div>

      {visible.length === 0 ? (
        <div className="rounded-xl border border-dashed border-black/15 p-10 text-center text-sm text-black/60 dark:border-white/15 dark:text-white/60">
          {showSpam
            ? "Nothing has been filtered. Anything caught by the spam trap is kept here rather than thrown away."
            : "Nothing in the inbox."}
        </div>
      ) : (
        <ul className="space-y-3">
          {visible.map((r) => (
            <li
              key={r.id}
              className={`rounded-xl border p-4 ${
                r.read || r.spam
                  ? "border-black/10 dark:border-white/10"
                  : "border-black/25 dark:border-white/25"
              }`}
            >
              <div className="mb-2 flex items-center gap-3 text-xs text-black/50 dark:text-white/50">
                <span className="font-medium text-black/70 dark:text-white/70">{r.formName}</span>
                <span>{when(r.createdAt)}</span>
                {!r.read && !r.spam && (
                  <span className="rounded-full bg-black px-2 py-0.5 text-[10px] font-medium text-white dark:bg-white dark:text-black">
                    New
                  </span>
                )}
                <div className="grow" />
                <button
                  disabled={busy}
                  onClick={() => patch({ ids: [r.id], read: !r.read })}
                  className="hover:text-black disabled:opacity-50 dark:hover:text-white"
                >
                  {r.read ? "Mark unread" : "Mark read"}
                </button>
                <button
                  disabled={busy}
                  onClick={() => patch({ ids: [r.id], spam: !r.spam })}
                  className="hover:text-black disabled:opacity-50 dark:hover:text-white"
                >
                  {r.spam ? "Not spam" : "Mark spam"}
                </button>
              </div>
              {r.fields.length === 0 ? (
                <p className="text-sm text-black/50 dark:text-white/50">(empty)</p>
              ) : (
                r.fields.map(([k, v]) => <Field key={k} name={k} value={v} />)
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

