import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { pathToFileURL } from "node:url";

const ROOT = "C:/Users/edmem/kodely-prod";
const PORT = Number(process.env.PROBE_PORT ?? 3003);

for (const line of fs.readFileSync(path.join(ROOT, ".env"), "utf8").split(/\r?\n/)) {
  const m = /^([A-Z_][A-Z0-9_]*)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}

const { PrismaClient } = await import(
  pathToFileURL(path.join(ROOT, "node_modules/@prisma/client/index.js")).href
);
const db = new PrismaClient();

const IP_SALT = process.env.FORM_IP_SALT ?? "kodely:form-submission:v1";
const hashIp = (ip) => crypto.createHash("sha256").update(`${IP_SALT}:${ip}`).digest("hex");

const fixture = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
const LIVE = fixture.published;
const DRAFT = fixture.draft;

function req({ method = "POST", host, path: p, headers = {}, body }) {
  return new Promise((resolve, reject) => {
    const data = body === undefined ? null : Buffer.from(body, "utf8");
    const r = http.request(
      {
        host: "127.0.0.1",
        port: PORT,
        method,
        path: p,
        headers: {
          host,
          ...(data ? { "content-length": String(data.length) } : {}),
          ...headers,
        },
      },
      (res) => {
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: Buffer.concat(chunks).toString("utf8"),
          }),
        );
      },
    );
    r.on("error", reject);
    if (data) r.write(data);
    r.end();
  });
}

function form(slug, { ip, body, origin, contentType = "application/x-www-form-urlencoded", formName = "contact", host }) {
  const h = host ?? `${slug}.kodely.site`;
  return req({
    host: h,
    path: `/__forms/${formName}`,
    headers: {
      "content-type": contentType,
      ...(origin === null ? {} : { origin: origin ?? `https://${h}` }),
      ...(ip ? { "cf-connecting-ip": ip } : {}),
    },
    body,
  });
}

const results = [];
function check(name, pass, detail) {
  results.push({ name, pass, detail });
  console.log(`${pass ? "PASS" : "FAIL"}  ${name}${detail ? `  — ${detail}` : ""}`);
}

const title = (b) => (b.match(/<h1[^>]*>([^<]*)<\/h1>/) ?? [, b.slice(0, 60)])[1];

// ─────────────────────────────────────────────────────────────────────────────
// 1. The page itself still serves, and still carries the unchanged CSP.
{
  const r = await req({ method: "GET", host: `${LIVE}.kodely.site`, path: "/" });
  const csp = r.headers["content-security-policy"] ?? "";
  check("GET published site serves", r.status === 200, `status ${r.status}`);
  check(
    "CSP unchanged: form-action 'self', connect-src 'none'",
    csp.includes("form-action 'self'") && csp.includes("connect-src 'none'") && !csp.includes("kodely.me"),
    csp.slice(0, 90) + "…",
  );
}

// 2. A submission from the site's own host lands.
{
  const r = await form(LIVE, {
    ip: "203.0.113.10",
    body: "name=Ada+Lovelace&email=ada%40example.com&message=Hello+%3Cscript%3Ealert(1)%3C%2Fscript%3E",
  });
  check("valid submission accepted", r.status === 200, `status ${r.status} / ${title(r.body)}`);

  const row = await db.formSubmission.findFirst({
    where: { project: { slug: LIVE } },
    orderBy: { createdAt: "desc" },
  });
  check("row stored", !!row, row ? `formName=${row.formName}` : "no row");
  check(
    "fields stored verbatim, not escaped/mangled",
    row?.fields?.message === "Hello <script>alert(1)</script>" && row?.fields?.name === "Ada Lovelace",
    JSON.stringify(row?.fields),
  );
  check("ipHash is a hash, not the address", row?.ipHash === hashIp("203.0.113.10"), row?.ipHash?.slice(0, 16) + "…");
  check("not flagged as spam", row?.spam === false, String(row?.spam));
  check("body echoes nothing submitted", !/(Ada|alert\(1\))/.test((await form(LIVE, { ip: "203.0.113.11", body: "name=x" })).body), "");
}

// 3. Unpublished project is refused.
{
  const r = await form(DRAFT, { ip: "203.0.113.20", body: "name=x&message=y" });
  check("unpublished project refused", r.status === 404, `status ${r.status}`);
  const n = await db.formSubmission.count({ where: { project: { slug: DRAFT } } });
  check("nothing stored for unpublished project", n === 0, `${n} rows`);
}

// 4. Unknown slug is refused, and identically.
{
  const r = await form("no-such-site-anywhere", { ip: "203.0.113.21", body: "name=x" });
  check("unknown slug refused", r.status === 404, `status ${r.status}`);
}

// 5. Wrong host (the app's own domain) cannot be used to submit.
{
  const r = await req({
    host: "kodely.me",
    path: `/api/site/${LIVE}/__forms/contact`,
    headers: { "content-type": "application/x-www-form-urlencoded", origin: "https://kodely.me", "cf-connecting-ip": "203.0.113.22" },
    body: "name=x",
  });
  check("app domain cannot submit", r.status === 404, `status ${r.status}`);
}

// 6. Cross-site origin refused.
{
  const r = await form(LIVE, { ip: "203.0.113.23", body: "name=x", origin: "https://attacker.example" });
  check("foreign Origin refused", r.status === 403, `status ${r.status}`);
}

// 7. Missing Origin refused.
{
  const r = await form(LIVE, { ip: "203.0.113.24", body: "name=x", origin: null });
  check("missing Origin refused", r.status === 403, `status ${r.status}`);
}

// 8. Wrong content type refused.
{
  const r = await form(LIVE, { ip: "203.0.113.25", body: '{"name":"x"}', contentType: "application/json" });
  check("JSON body refused", r.status === 415, `status ${r.status}`);
}

// 9. Oversized body refused unread.
{
  const r = await form(LIVE, { ip: "203.0.113.26", body: "message=" + "a".repeat(40_000) });
  check("oversized body refused", r.status === 413, `status ${r.status}`);
}

// 10. Oversized single value refused.
{
  const r = await form(LIVE, { ip: "203.0.113.27", body: "message=" + "a".repeat(6_000) });
  check("over-long field refused", r.status === 413, `status ${r.status}`);
}

// 11. Too many fields refused.
{
  const body = Array.from({ length: 20 }, (_, i) => `f${i}=v`).join("&");
  const r = await form(LIVE, { ip: "203.0.113.28", body });
  check("too many fields refused", r.status === 400, `status ${r.status}`);
}

// 12. Empty submission refused.
{
  const r = await form(LIVE, { ip: "203.0.113.29", body: "name=&message=" });
  check("empty submission refused", r.status === 400, `status ${r.status}`);
}

// 13. Honeypot: accepted, stored, flagged, not emailed.
{
  const r = await form(LIVE, { ip: "203.0.113.30", body: "name=Bot&_gotcha=http%3A%2F%2Fspam" });
  check("honeypot gets a normal-looking 200", r.status === 200, `status ${r.status}`);
  const row = await db.formSubmission.findFirst({
    where: { project: { slug: LIVE }, ipHash: hashIp("203.0.113.30") },
    orderBy: { createdAt: "desc" },
  });
  check("honeypot submission stored and flagged", row?.spam === true, `spam=${row?.spam}`);
  check("honeypot value itself not stored", row && !("_gotcha" in row.fields), JSON.stringify(row?.fields));
}

// 14. Timing check.
{
  const r = await form(LIVE, { ip: "203.0.113.31", body: `name=Quick&_t=${Date.now()}` });
  const row = await db.formSubmission.findFirst({
    where: { project: { slug: LIVE }, ipHash: hashIp("203.0.113.31") },
    orderBy: { createdAt: "desc" },
  });
  check("instant fill flagged by timing check", r.status === 200 && row?.spam === true, `spam=${row?.spam}`);
}
{
  const r = await form(LIVE, { ip: "203.0.113.32", body: `name=Human&_t=${Date.now() - 30_000}` });
  const row = await db.formSubmission.findFirst({
    where: { project: { slug: LIVE }, ipHash: hashIp("203.0.113.32") },
    orderBy: { createdAt: "desc" },
  });
  check("realistic fill time not flagged", r.status === 200 && row?.spam === false, `spam=${row?.spam}`);
}

// 15. _next redirect, and that it cannot leave the site.
{
  const r = await form(LIVE, { ip: "203.0.113.33", body: "name=x&_next=%2Fthanks" });
  check("_next redirects with 303", r.status === 303 && r.headers.location === "/thanks", `${r.status} ${r.headers.location}`);
}
{
  const r = await form(LIVE, { ip: "203.0.113.34", body: "name=x&_next=%2F%2Fattacker.example%2Fx" });
  check("protocol-relative _next ignored", r.status === 200 && !r.headers.location, `${r.status} ${r.headers.location ?? "no redirect"}`);
}
{
  const r = await form(LIVE, { ip: "203.0.113.35", body: "name=x&_next=https%3A%2F%2Fattacker.example" });
  check("absolute _next ignored", r.status === 200 && !r.headers.location, `${r.status} ${r.headers.location ?? "no redirect"}`);
}

// 16. Only /__forms/<name> is a POST surface.
{
  const r = await req({
    host: `${LIVE}.kodely.site`,
    path: "/index.html",
    headers: { "content-type": "application/x-www-form-urlencoded", origin: `https://${LIVE}.kodely.site`, "cf-connecting-ip": "203.0.113.36" },
    body: "name=x",
  });
  check("POST to a normal path is a 404", r.status === 404, `status ${r.status}`);
  const g = await req({ method: "GET", host: `${LIVE}.kodely.site`, path: "/__forms/contact" });
  check("GET on the form path is a 404", g.status === 404, `status ${g.status}`);
}
{
  const r = await form(LIVE, { ip: "203.0.113.37", body: "name=x", formName: "Contact%20Form" });
  check("bad form name refused", r.status === 404, `status ${r.status}`);
}

// 17. Burst limiter: the 9th request in five minutes from one address.
{
  const ip = "203.0.113.40";
  const seen = [];
  for (let i = 0; i < 10; i++) {
    const r = await form(LIVE, { ip, body: `name=burst${i}` });
    seen.push(r.status);
  }
  const first429 = seen.indexOf(429);
  check("burst limit trips", first429 === 8, `statuses ${seen.join(",")}`);
  const stored = await db.formSubmission.count({ where: { ipHash: hashIp(ip) } });
  check("refused burst requests store nothing", stored === 8, `${stored} rows stored`);
}

// 18. Durable per-IP limit, seeded so the burst limiter is not what refuses it.
{
  const ip = "203.0.113.50";
  const project = await db.project.findUnique({ where: { slug: LIVE }, select: { id: true } });
  await db.formSubmission.createMany({
    data: Array.from({ length: 15 }, (_, i) => ({
      projectId: project.id,
      formName: "contact",
      fields: { seeded: String(i) },
      ipHash: hashIp(ip),
      createdAt: new Date(Date.now() - i * 60_000),
    })),
  });
  const r = await form(LIVE, { ip, body: "name=x" });
  check("durable per-IP hourly limit trips", r.status === 429, `status ${r.status}`);
}

// 19. Durable per-project limit.
{
  const project = await db.project.findUnique({ where: { slug: LIVE }, select: { id: true } });
  const already = await db.formSubmission.count({
    where: { projectId: project.id, createdAt: { gte: new Date(Date.now() - 3_600_000) } },
  });
  const need = Math.max(0, 60 - already);
  await db.formSubmission.createMany({
    data: Array.from({ length: need }, (_, i) => ({
      projectId: project.id,
      formName: "contact",
      fields: { seeded: String(i) },
      ipHash: hashIp(`198.51.100.${i % 250}`),
      createdAt: new Date(Date.now() - (i % 50) * 60_000),
    })),
  });
  const r = await form(LIVE, { ip: "203.0.113.60", body: "name=x" });
  check("durable per-project hourly limit trips", r.status === 429, `status ${r.status}`);
  check(
    "per-project refusal does not reveal whose quota it was",
    !/site|quota|owner/i.test(r.body),
    title(r.body),
  );
}

console.log("");
const failed = results.filter((r) => !r.pass);
console.log(`${results.length - failed.length}/${results.length} passed`);
if (failed.length) console.log("FAILED: " + failed.map((f) => f.name).join(" | "));
await db.$disconnect();
process.exit(failed.length ? 1 : 0);

