import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { pathToFileURL } from "node:url";

const ROOT = "C:/Users/edmem/kodely-prod";
const PORT = Number(process.env.PROBE_PORT ?? 3003);

for (const line of fs.readFileSync(path.join(ROOT, ".env"), "utf8").split(/\r?\n/)) {
  const m = /^([A-Z_][A-Z0-9_]*)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}
const { PrismaClient } = await import(
  pathToFileURL(path.join(ROOT, "node_modules/@prisma/client/index.js")).href
);
const db = new PrismaClient();

const fixture = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));

function req({ method = "GET", path: p, headers = {}, body }) {
  return new Promise((resolve, reject) => {
    const data = body === undefined ? null : Buffer.from(body, "utf8");
    const r = http.request(
      {
        host: "127.0.0.1",
        port: PORT,
        method,
        path: p,
        headers: { host: `localhost:${PORT}`, ...(data ? { "content-length": String(data.length) } : {}), ...headers },
      },
      (res) => {
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks).toString("utf8") }),
        );
      },
    );
    r.on("error", reject);
    if (data) r.write(data);
    r.end();
  });
}

const results = [];
const check = (name, pass, detail) => {
  results.push({ name, pass });
  console.log(`${pass ? "PASS" : "FAIL"}  ${name}${detail ? `  — ${detail}` : ""}`);
};

// A session for the fixture owner, and one for an unrelated user.
async function sessionFor(userId) {
  const token = crypto.randomBytes(32).toString("base64url");
  await db.session.create({
    data: {
      userId,
      tokenHash: crypto.createHash("sha256").update(token).digest("hex"),
      expiresAt: new Date(Date.now() + 3_600_000),
    },
  });
  return `kodely_session=${token}`;
}

const stamp = Date.now();
const stranger = await db.user.create({
  data: { email: `formtest-stranger-${stamp}@example.invalid` },
});

const ownerCookie = await sessionFor(fixture.userId);
const strangerCookie = await sessionFor(stranger.id);

// Make sure there is something to look at, including one hostile value.
const project = await db.project.findUnique({ where: { slug: fixture.published }, select: { id: true } });
const hostile = await db.formSubmission.create({
  data: {
    projectId: project.id,
    formName: "contact",
    fields: {
      name: '<img src=x onerror="alert(1)">',
      message: "line one\nline two & <b>bold</b>",
    },
    ipHash: "deadbeef",
  },
});

// 1. Unauthenticated → redirected to login, never the data.
{
  const r = await req({ path: `/projects/${project.id}/submissions` });
  check(
    "submissions page requires a session",
    (r.status === 307 || r.status === 302) && (r.headers.location ?? "").includes("/login"),
    `${r.status} → ${r.headers.location}`,
  );
}

// 2. A stranger cannot read someone else's submissions.
{
  const r = await req({ path: `/projects/${project.id}/submissions`, headers: { cookie: strangerCookie } });
  const leaked = r.body.includes("onerror") || r.body.includes("line two");
  check(
    "another user cannot read them",
    !leaked && (r.status === 307 || r.status === 302),
    `${r.status} → ${r.headers.location ?? ""}`,
  );
}

// 3. The owner can, and hostile content is escaped rather than rendered.
{
  const r = await req({ path: `/projects/${project.id}/submissions`, headers: { cookie: ownerCookie } });
  check("owner can read submissions", r.status === 200, `status ${r.status}`);
  check(
    "submitted markup is escaped, not rendered",
    r.body.includes("&lt;img src=x onerror=") && !r.body.includes('<img src=x onerror="alert(1)">'),
    "",
  );
  check("submission content is present", r.body.includes("line two"), "");
}

// 4. Mark read, scoped to the owner.
{
  const r = await req({
    method: "PATCH",
    path: `/api/forms/${project.id}`,
    headers: { cookie: strangerCookie, "content-type": "application/json" },
    body: JSON.stringify({ ids: [hostile.id], read: true }),
  });
  check("stranger cannot mark another project's submissions", r.status === 404, `status ${r.status}`);

  const ok = await req({
    method: "PATCH",
    path: `/api/forms/${project.id}`,
    headers: { cookie: ownerCookie, "content-type": "application/json" },
    body: JSON.stringify({ ids: [hostile.id], read: true }),
  });
  const row = await db.formSubmission.findUnique({ where: { id: hostile.id } });
  check("owner can mark read", ok.status === 200 && row.readAt !== null, `status ${ok.status}`);

  const spam = await req({
    method: "PATCH",
    path: `/api/forms/${project.id}`,
    headers: { cookie: ownerCookie, "content-type": "application/json" },
    body: JSON.stringify({ ids: [hostile.id], spam: true }),
  });
  const row2 = await db.formSubmission.findUnique({ where: { id: hostile.id } });
  check("owner can flag spam", spam.status === 200 && row2.spam === true, `status ${spam.status}`);
}

// 5. An id from someone else's project is ignored even with a valid own project id.
{
  const other = await db.project.create({
    data: { userId: stranger.id, name: "Stranger", slug: `formtest-stranger-${stamp}` },
  });
  const r = await req({
    method: "PATCH",
    path: `/api/forms/${other.id}`,
    headers: { cookie: strangerCookie, "content-type": "application/json" },
    body: JSON.stringify({ ids: [hostile.id], read: true }),
  });
  const row = await db.formSubmission.findUnique({ where: { id: hostile.id } });
  check(
    "cross-project id in an owned request updates nothing",
    r.status === 200 && JSON.parse(r.body).updated === 0 && row.spam === true,
    r.body.slice(0, 60),
  );
}

// 6. Unauthenticated PATCH.
{
  const r = await req({
    method: "PATCH",
    path: `/api/forms/${project.id}`,
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ read: true }),
  });
  check("unauthenticated PATCH refused", r.status === 401, `status ${r.status}`);
}

console.log("");
const failed = results.filter((r) => !r.pass);
console.log(`${results.length - failed.length}/${results.length} passed`);
if (failed.length) console.log("FAILED: " + failed.map((f) => f.name).join(" | "));

// Tear down just what this file created.
await db.user.delete({ where: { id: stranger.id } });
await db.session.deleteMany({ where: { userId: fixture.userId } });
await db.$disconnect();
process.exit(failed.length ? 1 : 0);

// The smallest SMTP server that nodemailer will talk to. Captures each message
// to a JSON-lines file so the probe can inspect the real headers we emit.
import net from "node:net";
import fs from "node:fs";

const OUT = process.argv[2];
fs.writeFileSync(OUT, "");

net
  .createServer((sock) => {
    let buf = "";
    let inData = false;
    let data = "";
    let envelope = { to: [], from: null };

    const say = (line) => sock.write(line + "\r\n");
    say("220 sink ESMTP");

    sock.on("data", (chunk) => {
      buf += chunk.toString("utf8");

      if (inData) {
        const end = buf.indexOf("\r\n.\r\n");
        if (end === -1) return;
        data += buf.slice(0, end);
        buf = buf.slice(end + 5);
        inData = false;
        fs.appendFileSync(OUT, JSON.stringify({ envelope, data }) + "\n");
        data = "";
        envelope = { to: [], from: null };
        say("250 2.0.0 Ok: queued");
      }

      let nl;
      while (!inData && (nl = buf.indexOf("\r\n")) !== -1) {
        const line = buf.slice(0, nl);
        buf = buf.slice(nl + 2);
        const up = line.toUpperCase();

        if (up.startsWith("EHLO") || up.startsWith("HELO")) {
          say("250-sink");
          say("250-AUTH PLAIN LOGIN");
          say("250 SMTPUTF8");
        } else if (up.startsWith("AUTH LOGIN")) {
          say("334 VXNlcm5hbWU6");
        } else if (up.startsWith("AUTH PLAIN")) {
          say("235 2.7.0 Accepted");
        } else if (up.startsWith("MAIL FROM")) {
          envelope.from = line.slice(10);
          say("250 2.1.0 Ok");
        } else if (up.startsWith("RCPT TO")) {
          envelope.to.push(line.slice(8));
          say("250 2.1.5 Ok");
        } else if (up === "DATA") {
          inData = true;
          say("354 End data with <CR><LF>.<CR><LF>");
        } else if (up === "QUIT") {
          say("221 2.0.0 Bye");
          sock.end();
        } else if (up === "RSET") {
          say("250 2.0.0 Ok");
        } else {
          // Base64 credential lines during AUTH LOGIN land here.
          say(/^[A-Za-z0-9+/=]*$/.test(line) ? "334 UGFzc3dvcmQ6" : "250 2.0.0 Ok");
          if (/^[A-Za-z0-9+/=]+$/.test(line) && line.length > 4) {
            // Second credential line: accept.
            say("235 2.7.0 Accepted");
          }
        }
      }
    });
    sock.on("error", () => undefined);
  })
  .listen(2525, "127.0.0.1", () => console.log("sink listening on 2525"));

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const ROOT = "C:/Users/edmem/kodely-prod";
const PORT = 3003;
const SP = path.dirname(process.argv[1]);
const MAILFILE = path.join(SP, "mail.jsonl");

for (const line of fs.readFileSync(path.join(ROOT, ".env"), "utf8").split(/\r?\n/)) {
  const m = /^([A-Z_][A-Z0-9_]*)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}
const { PrismaClient } = await import(
  pathToFileURL(path.join(ROOT, "node_modules/@prisma/client/index.js")).href
);
const db = new PrismaClient();

const fixture = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
const LIVE = fixture.published;

function post(body, ip, formName = "contact") {
  const host = `${LIVE}.kodely.site`;
  const data = Buffer.from(body, "utf8");
  return new Promise((resolve, reject) => {
    const r = http.request(
      {
        host: "127.0.0.1",
        port: PORT,
        method: "POST",
        path: `/__forms/${formName}`,
        headers: {
          host,
          origin: `https://${host}`,
          "content-type": "application/x-www-form-urlencoded",
          "content-length": String(data.length),
          "cf-connecting-ip": ip,
        },
      },
      (res) => {
        const c = [];
        res.on("data", (x) => c.push(x));
        res.on("end", () => resolve({ status: res.statusCode, body: Buffer.concat(c).toString() }));
      },
    );
    r.on("error", reject);
    r.write(data);
    r.end();
  });
}

const results = [];
const check = (n, p, d) => {
  results.push({ n, p });
  console.log(`${p ? "PASS" : "FAIL"}  ${n}${d ? `  — ${d}` : ""}`);
};

const readMail = () =>
  fs
    .readFileSync(MAILFILE, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((l) => JSON.parse(l));

const settle = (ms) => new Promise((r) => setTimeout(r, ms));

// Clear the slate.
await db.formSubmission.deleteMany({ where: { project: { slug: { startsWith: "formtest-" } } } });
fs.writeFileSync(MAILFILE, "");

// 1. Ordinary submission → one email, to the owner, with a Reply-To.
{
  const r = await post(
    "name=Ada+Lovelace&email=ada%40example.com&message=Please+call+me+about+a+quote",
    "198.51.100.1",
  );
  check("submission accepted", r.status === 200, `status ${r.status}`);
  await settle(2500);
  const mail = readMail();
  check("exactly one email sent", mail.length === 1, `${mail.length} messages`);
  const m = mail[0];
  if (m) {
    check("addressed to the project owner from the database", m.envelope.to.some((t) => t.includes(fixture.email)), m.envelope.to.join(","));
    check("envelope sender is ours, never the visitor", /noreply@kodely\.me/.test(m.envelope.from), m.envelope.from);
    check("Reply-To carries the visitor's address", /^Reply-To: ada@example\.com\s*$/m.test(m.data), (m.data.match(/^Reply-To:.*$/m) ?? ["(none)"])[0]);
    check("subject names no submitted content", /^Subject: .*/m.test(m.data) && !/Ada/.test((m.data.match(/^Subject:.*$/m) ?? [""])[0]), (m.data.match(/^Subject:.*$/m) ?? [""])[0]);
    check("body carries the submission", /Please call me about a quote/.test(m.data), "");
  }
}

// 2. Header injection attempt in the address field.
{
  fs.writeFileSync(MAILFILE, "");
  const evil = encodeURIComponent("attacker@example.com\r\nBcc: victim@example.com");
  await post(`name=Mallory&email=${evil}&message=hi`, "198.51.100.2");
  await settle(2500);
  const mail = readMail();
  const m = mail[0];
  check("still sent", mail.length === 1, `${mail.length} messages`);
  if (m) {
    check("no Bcc header injected", !/^Bcc:/im.test(m.data), (m.data.match(/^Bcc:.*$/im) ?? ["(none)"])[0]);
    check("no Reply-To at all for a malformed address", !/^Reply-To:/im.test(m.data), (m.data.match(/^Reply-To:.*$/im) ?? ["(none)"])[0]);
    check("only the owner is an envelope recipient", m.envelope.to.length === 1, m.envelope.to.join(","));
    check("the attempt is still visible in the body as text", /attacker@example.com/.test(m.data), "");
  }
}

// 3. HTML in a field must not become markup in the HTML part.
{
  fs.writeFileSync(MAILFILE, "");
  await post("name=" + encodeURIComponent('<img src=x onerror="alert(1)">') + "&message=hi", "198.51.100.3");
  await settle(2500);
  const m = readMail()[0];
  if (m) {
    // Quoted-printable may wrap; decode softly for the check.
    const decoded = m.data.replace(/=\r\n/g, "").replace(/=3D/g, "=").replace(/=22/g, '"');
    check(
      "submitted markup escaped in the HTML part",
      decoded.includes("&lt;img src=x onerror=") && !decoded.includes('<img src=x onerror="alert(1)">'),
      "",
    );
  } else {
    check("submitted markup escaped in the HTML part", false, "no mail captured");
  }
}

// 4. Honeypot submissions are stored but never emailed.
{
  fs.writeFileSync(MAILFILE, "");
  const r = await post("name=Bot&_gotcha=x", "198.51.100.4");
  await settle(2000);
  const row = await db.formSubmission.findFirst({
    where: { project: { slug: LIVE } },
    orderBy: { createdAt: "desc" },
  });
  check(
    "flagged submission stored but not emailed",
    r.status === 200 && row.spam === true && readMail().length === 0,
    `spam=${row?.spam} mails=${readMail().length}`,
  );
}

// 5. Email volume cap: past EMAIL_MAX_PER_HOUR the mail stops, the rows do not.
{
  fs.writeFileSync(MAILFILE, "");
  const project = await db.project.findUnique({ where: { slug: LIVE }, select: { id: true } });
  const before = await db.formSubmission.count({ where: { projectId: project.id } });
  await db.formSubmission.createMany({
    data: Array.from({ length: 12 }, (_, i) => ({
      projectId: project.id,
      formName: "contact",
      fields: { seeded: String(i) },
      ipHash: `seed-${i}`,
      createdAt: new Date(Date.now() - i * 60_000),
    })),
  });
  const r = await post("name=Late&message=still+recorded", "198.51.100.5");
  await settle(2500);
  const after = await db.formSubmission.count({ where: { projectId: project.id } });
  check(
    "past the hourly email cap the submission is still stored",
    r.status === 200 && after === before + 13,
    `${before} → ${after}`,
  );
  check("…and no email is sent", readMail().length === 0, `${readMail().length} messages`);
}

console.log("");
const failed = results.filter((r) => !r.p);
console.log(`${results.length - failed.length}/${results.length} passed`);
if (failed.length) console.log("FAILED: " + failed.map((f) => f.n).join(" | "));
await db.$disconnect();
process.exit(failed.length ? 1 : 0);

